List<T> merge<T extends Comparable<T>>(List<T> left, List<T> right) {
  List<T> result = [];
  int i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (left[i].compareTo(right[j]) < 0) {
      result.add(left[i]);
      i++;
    } else {
      result.add(right[j]);
      j++;
    }
  }

  while (i < left.length) result.add(left[i]);
  while (j < right.length) result.add(right[j]);

  return result;
}

