bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String word = s.substring(j, i);
        if (wordSet.contains(word)) {
          dp[i] = true;
          break;
        }
      }
    }
  }
  return dp[s.length];
}

List<String> wordBreakAll(String s, List<String> wordDict) {
  Map<String, List<String>> memo = {};

  List<String> wordBreakAllRec(String s, int start) {
    if (start == s.length) return [s];

    if (memo.containsKey(s.substring(start, s.length))) {
      return memo[s.substring(start, s.length)]!;
    }

    List<String> result = [];
    for (int j = start; j < s.length; j++) {
      if (wordBreakAllRec(s, j + 1)) {
        String word = s.substring(start, j + 1);
        if (wordDict.contains(word)) {
          result.add(word);
        }
      }
    }

    memo[s.substring(start, s.length)] = result;
    return result;
  }

  return wordBreakAllRec(s, 0);
}

