bool wordBreak(String s, String word) {
  Set<String> wordSet = word.split(' ');
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (String word in wordSet) {
      if (s.substring(0, i) == word && dp[i - word.length]) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

void allWordBreak(String s, List<String> wordBreak) {
  List<List<String>> result = [];
  List<String> curr = [];

  void backtrack(int idx) {
    if (idx == s.length) {
      result.add(List<String>.from(curr));
      return;
    }
    for (String word in wordBreak) {
      if (s.substring(idx, idx + word.length) == word) {
        curr.add(word);
        backtrack(idx + word.length);
        curr.removeLast();
      }
    }
  }

  backtrack(0);
  print("All possible segmentations:");
  for (var seg in result) {
    print(seg);
  }
}

int minWordBreak(String s, List<String> wordBreak) {
  Map<String, int> counts = {};
  for (String word in wordBreak) {
    counts[word] = (counts[word] ?? 0) + 1;
  }
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (String word in wordBreak) {
      if (s.substring(0, i) == word && counts[word]! > 0) {
        int cost = dp[i - word.length]! + 1;
        dp[i] = dp[i] < cost ? dp[i] : cost;
      }
    }
  }
  return dp[s.length] > s.length ? -1 : dp[s.length];
}

