class User {
  final String name;
  final Map<String, dynamic> permissions;

  User(this.name, [this.permissions = const {'read': false, 'write': false, 'admin': false}]);

  String getRole() {
    if (permissions.containsKey('admin')) {
      return 'admin';
    }
    if (permissions.containsKey('editor')) {
      return 'editor';
    }
    if (permissions.containsKey('viewer')) {
      return 'viewer';
    }
    return 'user';
  }

  void grantPermission(String permission) {
    if (!permissions.containsKey(permission)) {
      return;
    }
    permissions[permission] = true;
  }

  void revokePermission(String permission) {
    if (!permissions.containsKey(permission)) {
      return;
    }
    permissions[permission] = false;
  }
}

