      if (j < i) {
        return j;
      }
      return j - 1;
    });

    for (var j = i; j >= 0; j--) {
      nextIndices[j + 1] = nextIndices[j] + 1;
    }

    indices = nextIndices;
  }

  print('Total combinations: ${total < 100 ? total : "100+"}");
  print('Combinations: $result');
