    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) return false;
    }

    for (int i = row; i >= 0; i--) {
      if (board[i][col] == 1) return false;
    }

    int start = 0;
    if (row > col) {
      start = row - col;
    } else {
      start = col - row;
    }
    for (int i = 0; i < start; i++) {
      if (board[i][col] == 1) return false;
    }

    return true;
  }

  void place(List<List<int>> board, int row) {
    if (row == n) {
      solutions++;
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(board, row, col, n)) {
        board[row][col] = 1;
        place(board, row + 1);
        board[row][col] = 0;
      }
    }
  }

  place(board, 0);

  print('Solving N-Queens for N=$n');
  print('Total solutions: $solutions');
}

