/// Represents a quaternion in 4-dimensional space.
class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  /// Construct a quaternion from a normalized 3-vector.
  factory Quaternion(List<double> v) {
    double x = v[0], y = v[1], z = v[2], w = v[3];
    final double norm = x * x + y * y + z * z;
    if (norm == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm, y / norm, z / norm, 1.0 / norm);
  }

  /// Construct a quaternion from a 3-vector and a scalar.
  factory Quaternion.fromList(List<double> v, double s) {
    return Quaternion(v[0], v[1], v[2], s);
  }

  /// Construct a quaternion from two other quaternions.
  factory Quaternion.fromQuaternions(Quaternion q1, Quaternion q2) {
    return Quaternion(
      q1.x * q2.x - q1.y * q2.y - q1.z * q2.z - q1.w * q2.w,
      q1.x * q2.y + q1.y * q2.x + q1.z * q2.w - q1.w * q2.z,
      q1.x * q2.z - q1.y * q2.w + q1.z * q2.x - q1.w * q2.y,
      q1.x * q2.w + q1.y * q2.z - q1.z * q2.y + q1.w * q2.x,
    );
  }

  /// Calculate the norm (square root of sum of squares).
  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  /// Calculate the conjugate quaternion.
  Quaternion conjugate() {
    return Quaternion(x, -y, -z, w);
  }

  /// Calculate the inverse.
  Quaternion inverse() {
    final double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final double inv = 1.0 / n;
    return Quaternion(
      x * inv,
      -y * inv,
      -z * inv,
      w * inv,
    );
  }

  /// Calculate the complex conjugate.
  Quaternion complex() {
    return Quaternion(x + w, y + z, -w, -z);
  }

  /// Calculate the scaled quaternion.
  Quaternion operator *(double s) {
    return Quaternion(x * s, y * s, z * s, w * s);
  }

  /// Calculate the scaled quaternion.
  Quaternion operator *(Quaternion q) {
    return Quaternion(
      x * q.x - y * q.y - z * q.z - w * q.w,
      x * q.y + y * q.x + z * q.w - w * q.z,
      x * q.z - y * q.w + z * q.x - w * q.y,
      x * q.w + y * q.z - z * q.y + w * q.x,
    );
  }

  /// Calculate the addition.
  Quaternion operator +(Quaternion q) {
    return Quaternion(
      x + q.x,
      y + q.y,
      z + q.z,
      w + q.w,
    );
  }

  /// Calculate the subtraction.
  Quaternion operator -(Quaternion q) {
    return Quaternion(
      x - q.x,
      y - q.y,
      z - q.z,
      w - q.w,
    );
  }

  /// Calculate the complex conjugate.
  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

