/// Quaternion class for representing 4-dimensional vectors with
/// a real part and three imaginary parts.
class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  static const Quaternion zero = Quaternion(0.0, 0.0, 0.0, 1.0);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalized() {
    final d = norm();
    if (d == 0.0) return zero;
    return Quaternion(x / d, y / d, z / d, w / d);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    final d = norm();
    if (d == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final invD = 1.0 / d;
    return Quaternion(x * invD, y * invD, z * invD, -w * invD);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    final x = x * other.w - y * other.z - z * other.y + w * other.x;
    final y = x * other.z + y * other.w + z * other.x - w * other.y;
    final z = x * other.y - y * other.w + z * other.x + w * other.z;
    return Quaternion(x, y, z, other.w * w + w * x + z * y + w * z);
  }

  @override
  String toString() {
    final parts = <String>[
      'q1 = ${x.toStringAsFixed(3)} + $y i + $z j + $w k',
    ];
    if (norm() != 0.0) {
      parts.add('norm(q1) = ${norm().toStringAsFixed(3)}');
    }
    return parts.join(' ');
  }
}

