    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion q) {
    final x1 = x, y1 = y, z1 = z, w1 = w;
    final x2 = q.x, y2 = q.y, z2 = q.z, w2 = q.w;
    return Quaternion(
      (y1 * w2 - y2 * w1) + x1 * z2 + x2 * z1,
      (x1 * w2 - x2 * w1) + y1 * z2 + y2 * z1,
      (x1 * y2 - x2 * y1) + z1 * w2 + z2 * w1,
      (x1 * z2 - x2 * z1) + y1 * w2 + y2 * w1,
    );
  }

  Quaternion operator /(double scalar) {
    return Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);
  }

  Quaternion inverse() {
    final invW = 1 / w;
    return Quaternion(
      -x * invW,
      -y * invW,
      -z * invW,
      invW,
    );
  }

  Quaternion conjugate() {
    return Quaternion(x, -y, -z, w);
  }

  double norm() {
    return (x * x + y * y + z * z + w * w).sqrt();
  }

  Quaternion normalized() {
    final n = norm();
    return (x / n, y / n, z / n, w / n);
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

