class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion._internal(this._x, this._y, this._z, this._w);

  factory Quaternion(double x, double y, double z, double w) {
    return w == 0.0
        ? Quaternion._internal(x, y, z, 0.0)
        : Quaternion._internal(x / w, y / w, z / w, w);
  }

  factory Quaternion.fromList(List<double> list) {
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  double get x => _x;
  double get y => _y;
  double get z => _z;
  double get w => _w;

  double get magnitude => sqrt(x * x + y * y + z * z + w * w);

  const Quaternion operator +(other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator *(Quaternion other) =>
      Quaternion(x * other.w - y * other.z - z * other.y,
          y * other.w + x * other.z,
          z * other.w - x * other.y,
          x * other.w + y * other.z);

  const Quaternion operator *(List<double> list) =>
      Quaternion(x * list[0] - y * list[1] - z * list[2],
          y * list[0] + x * list[1],
          z * list[0] - x * list[2],
          x * list[0] + y * list[2]);

  const Quaternion operator /(double scalar) =>
      Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);

  const Quaternion operator /(Quaternion other) {
    final double denom = other.w * w;
    if (denom == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      (x * other.w - y * other.z - z * other.y) / denom,
      (y * other.w + x * other.z) / denom,
      (z * other.w - x * other.y) / denom,
      1 / denom,
    );
  }

  const Quaternion conjugate() => Quaternion(x, y, z, -w);

  const Quaternion normalized() {
    final double mag = magnitude;
    if (mag == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / mag, y / mag, z / mag, w / mag);
  }

  const Quaternion rotateZ(double angle) {
    final double sin = sin(angle);
    final double cos = cos(angle);
    return Quaternion(
      x * cos - z * sin,
      y * cos + z * sin,
      z * cos,
      w,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

