/// Quaternion class representing a 4-dimensional unit vector.
class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  static Quaternion fromList(List<double> list) {
    return Quaternion(
      list[0],
      list[1],
      list[2],
      list[3],
    );
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    double xx = x * x;
    double yy = y * y;
    double zz = z * z;
    double xy = x * y;
    double yz = y * z;
    double zw = z * w;
    double wx = x * w;
    double wy = y * w;
    double wz = z * w;
    return Quaternion(
      xx * w + wx + xy * w,
      xx * y + xy + yy * w,
      xx * z + xy + zz * w,
      yy * z + yy * w + zz * w,
    );
  }

  Quaternion get conjugate => Quaternion(x, y, z, -w);

  double get norm => sqrt(x * x + y * y + z * z + w * w);

  double get magnitude => sqrt(x * x + y * y + z * z);

  Quaternion get normalized => this * (1 / norm);

  Quaternion get inverse => this * (1 / (norm * norm));

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

