class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z,
          y * other.w + x * other.z,
          x * other.z - y * other.w,
          w * other.w - x * x - y * y);

  Quaternion conjugate() =>
      Quaternion(x, -y, -z, w);

  double norm() => x.abs() + y.abs() + z.abs() + w.abs();

  Quaternion normalized() {
    final double norm = norm();
    if (norm == 0.0) {
      return Quaternion.zero();
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion inverse() =>
      Quaternion(x, y, z, -w) * (1.0 / (x.abs() + y.abs() + z.abs() + w.abs()));

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

