  double get z;
  double get w;

  double get norm();

  Quaternion operator +(Quaternion other);
  Quaternion operator -(Quaternion other);
  Quaternion operator *(Quaternion other);

  Quaternion inverse();
  Quaternion conjugate();

  static Quaternion fromList(List<double> list);
  static Quaternion fromAngleAxis(double angle, List<double> axis);

  static Quaternion identity() => Quaternion(1.0, 0.0, 0.0, 0.0);

