}

class QuaternionImpl implements Quaternion {
  final double x, y, z, w;

  QuaternionImpl(this.x, this.y, this.z, this.w);

  QuaternionImpl._internal(this.x, this.y, this.z, this.w);

  factory QuaternionImpl(double x, double y, double z, double w) {
    return _internal._new(x, y, z, w);
  }

  factory QuaternionImpl.fromList(List<double> list) {
    return _internal._new(list[0], list[1], list[2], list[3]);
  }

  factory QuaternionImpl.fromAngleAxis(double angle, List<double> axis) {
    final double x = axis[0];
    final double y = axis[1];
    final double z = axis[2];
    return _internal._new(
      (x * x + y * y + z * z) * (1 - 2 * angle),
      2 * (x * y + z * w),
      2 * (x * z - y * w),
      x * y - z * w,
    );
  }

  static QuaternionImpl _new(
    double x,
    double y,
    double z,
    double w,
  ) =>
      QuaternionImpl._internal(x, y, z, w);

  @override
  double get x => _x;
  @override
  double get y => _y;
  @override
  double get z => _z;
  @override
  double get w => _w;

  @override
  double get norm() {
    return (x * x + y * y + z * z + w * w).sqrt();
  }

  @override
  Quaternion operator +(Quaternion other) =>
      QuaternionImpl(x + other.x, y + other.y, z + other.z, w + other.w);

  @override
  Quaternion operator -(Quaternion other) =>
      QuaternionImpl(x - other.x, y - other.y, z - other.z, w - other.w);

  @override
  Quaternion operator *(Quaternion other) =>
      QuaternionImpl(
        (x * other.w + other.x * w),
