int KMPSearch(String text, String pattern) {
  int patternLength = pattern.length;
  int n = text.length;
  List<int> lps = List<int>.filled(patternLength, 0);
  int i = 1;

  while (i < patternLength) {
    if (pattern[i] == pattern[lps[i - 1]]) {
      lps[i] = lps[i - 1] + 1;
      i++;
    } else {
      if (lps[i - 1] != 0) {
        i = lps[i - 1] + 1;
      } else {
        lps[i] = 0;
        i++;
      }
    }
  }

  int k = 0; 
  int j = 0; 
  while (j < n) {
    if (pattern[k] == text[j]) {
      k++;
      j++;
    }
    if (k == patternLength) {
      return k;
    }
    if (j < n && pattern[k] != text[j]) {
      if (k != 0) {
        k = lps[k - 1];
      } else {
        j++;
      }
    }
  }
  return -1;
}

