int kmpSearch(String text, String pattern) {
  int m = text.length;
  int n = pattern.length;

  if (n == 0 || m == 0 || n > m) {
    return -1;
  }

  List<int> lps = List<int>.filled(n, 0);

  int computeLPSArray(String pattern) {
    int len = 0; 
    int end = 0; 
    int lps = 0; 

    while (end < pattern.length) {
      if (pattern[end] == pattern[len]) {
        len++;
        end++;
        lps++;
      } else {
        if (len != 0) {
          len = lps;
        } else {
          end++;
        }
      }
    }
    return lps;
  }

  lps = computeLPSArray(pattern);

  int i = 0;
  int j = 0;

  while (i < m) {
    if (pattern[j] == text[i]) {
      i++;
      j++;
    }
    if (j == pattern.length) {
      return i - j;
    }
    if (i < m && pattern[j] != text[i]) {
      if (j != 0) {
        j = lps[j - 1];
      } else {
        i++;
      }
    }
  }
  return -1;
}

