  String pattern = 'AABAACAADAABAABA';
  String text = 'AABAACAADAABAABA';

  int patternLength = pattern.length;
  int n = text.length;


  List<int> kmpSearch(String pattern, String text) {
    int m = pattern.length;
    int n = text.length;

    List<int> result = [];

    int kmpSearchCore(String pattern, String text) {
      int i = 0; 
      int j = 0; 

      while (i < n) {
        if (text[i] == pattern[j]) {
          i++;
          j++;
        }
        if (j == pattern.length) {
          result.add(i - j); 
          j = kmpSearchFunction(pattern, i - j, j);
        } else if (i < n && text[i] != pattern[j]) {
          if (j != 0) {
            j = kmpSearchFunction(pattern, i, j);
          } else {
            i++;
          }
        }
      }
      return i;
    }

    int kmpSearchFunction(String pattern, int i, int j) {
      int len = pattern.length;
      int k = j - 1;

      while (k > 0 && pattern[k] != text[i]) {
        k--;
      }

      if (k > 0 && pattern[k] == text[i]) {
        return k + 1;
      }

      return j;
    }

    return kmpSearchCore(pattern, text);
  }

  List<int> result = kmpSearch(pattern, text);

  if (result.isEmpty) {
    print('\nPattern not found in the text.');
  } else {
    print('\nPattern found at indices: $result');
  }

