int fn0(List<int> temperatures, int target) {
  int n = temperatures.length;
  if (n == 0) return -1;
  if (n == 1) return temperatures[0] == target ? 0 : -1;

  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + temperatures[i];
  }

  int l = 0, r = n;
  while (l < r) {
    int m = (l + r) ~/ 2;
    if (prefix[m + 1] < target) {
      l = m + 1;
    } else {
      r = m;
    }
  }

  int idx = l;
  if (idx == n) return -1;
  if (prefix[idx] != target) {
    idx--;
    if (idx == 0) return -1;
  }

  return idx;
}

