int fn0(List<int> sortedDurations, int k) {
  int n = sortedDurations.length;
  if (n < 2 || k < 1) return 0;
  int total = 0;
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      int a = sortedDurations[i];
      int b = sortedDurations[j];
      if (a > b) continue;
      if (a == b) {
        if (i < j) total++;
      } else {
        int temp = a;
        a = b;
        b = temp;
        int c = (a - b) ~/ 2;
        total += c;
      }
    }
  }
  return total;
}

