import 'dart:async';
import 'dart:convert';
class User {
  String name = '';
  List<String> roles = [];

  void addRole(String role) {
    roles.add(role);
  }

  void removeRole(String role) {
    roles.remove(role);
  }

  bool hasRole(String role) {
    return roles.contains(role);
  }
}

class Role {
  String name = '';
  Map<String, bool> permissions = {};

  Role(this.name);
}

class Resource {
  String name = '';

  Resource(this.name);
}

class AccessControlSystem {
  Map<String, User> users = {};
  Map<String, Role> roles = {};
  Map<String, Resource> resources = {};

  void grantPermissions(String user, String role, String resource, bool granted) {
    if (granted) {
      users[user]!.addRole(role);
      resources[resource]!.addGrantee(user);
    } else {
      users[user]!.removeRole(role);
      resources[resource]!.removeGrantee(user);
    }
  }

  bool checkAccess(String user, String role, String resource) {
    if (resources[resource] == null) {
      print('  ❌ Resource "${resource}" not found');
      return false;
    }
    if (!users.containsKey(user)) {
      print('  ❌ User "${user}" not found');
      return false;
    }

    bool hasPermissions = false;
    roles[role]!.permissions.forEach((key, value) {
      if (value == true) {
        hasPermissions = true;
      }
    });

    bool hasRole = false;
    users[user]!.roles.forEach((roleName) {
      if (roleName == role) {
        hasRole = true;
      }
    });

    if (hasPermissions && hasRole) {
      return true;
    } else {
      return false;
    }
  }

  void printUserSummary(String user) {
    print('User: ${user.padRight(10)}');
    print('Permissions: ${users[user]!.permissions.keys.join(', ')}\n');
  }

  void printRoleSummary(String role) {
    print('Role: ${role.padRight(10)}');
    print('Permissions: ${roles[role]!.permissions.keys.join(', ')}\n');
  }

  void printResourceSummary(String resource) {
    print('Resource: ${resource.padRight(10)}');
    print('Grantees: ${resources[resource]!.grantees.join(', ')}\n');
  }

  void printAuditLog() {
    print('--- Audit Log ---\n');
    print('Recent Access Attempts:\n');
    users.forEach((user, userObject) {
      userObject.roles.forEach((role) {
        print('  ${user.padLeft(8)} ${role} attempted to access:');
        resources.forEach((resource, resourceObject) {
          if (resourceObject.hasGrantee(user)) {
            print('    • ${resource}');
          }
        });
        print('  — ${userObject.hasRole(role) ? '✓' : '✗'}');
      });
    });
  }

  void printSystemSummary() {
    print('\n=== System Summary ===');
    print('Total Users: ${users.length}\n');
    users.forEach((user, userObject) {
      printUserSummary(user);
    });
    print('\nTotal Roles: ${roles.length}\n');
    roles.forEach((role, roleObject) {
      printRoleSummary(role);
    });
    print('\nTotal Resources: ${resources.length}\n');
    resources.forEach((resource, resourceObject) {
      printResourceSummary(resource);
    });
    printAuditLog();
  }
}

