bool testAccess(String user, String resource, List<String> role) {
  if (role.isEmpty) return false;

  for (final resource in resources.keys) {
    if (!resources[resource]!.contains(role[0])) {
      return false;
    }
  }

  for (final role in role.sublist(1)) {
    for (final user in users.keys) {
      if (users[user]!.contains(role)) {
        return false;
      }
    }
  }

  return true;
}

String generateRoleHierarchy() {
  final Map<String, List<String>> hierarchy = {};
  for (final role in permissions.keys) {
    final parent = permissions[role]!.isEmpty ? 'admin' : permissions[role]![0];
    hierarchy[parent] = (hierarchy[parent] ?? [])..add(role);
  }
  final Map<String, int> depth = {};
  for (final role in hierarchy.keys) {
    if (hierarchy[role]!.isEmpty) {
      depth[role] = 0;
    } else {
      depth[role] = depth[hierarchy[role]![0]]! + 1;
    }
  }
  final StringBuffer sb = StringBuffer();
  for (final role in hierarchy.keys) {
    final depthValue = depth[role]!;
    final level = '_'.padLeft(depthValue, '-');
    sb.write('$level $role: ${hierarchy[role]}');
  }
  return sb.toString();
}

String getRecentAccessLog() {
  final Map<String, List<String>> log = {};
  for (final user in users.keys) {
    for (final resource in resources.keys) {
