import 'dart:async';
import 'dart:convert';
class Role {
  String name;
  List<String> permissions;
  Role? parent;

  Role(this.name, this.permissions, [this.parent]);

  bool hasPermission(String permission) {
    return permissions.contains(permission);
  }
}

class Resource {
  String name;
  List<String> permissions;

  Resource(this.name, this.permissions);

  bool hasPermission(String action, String resource) {
    if (action == 'read') {
      return permissions.contains(resource);
    } else if (action == 'write') {
      return permissions.contains('-' + resource);
    } else if (action == 'delete') {
      return permissions.contains('delete' + resource);
    }
    return false;
  }
}

class User {
  String name;
  Map<String, List<String>> roles;

  User(this.name, [this.roles = const <String, List<String>>]);

  bool hasRole(String roleName) {
    return roles.containsKey(roleName);
  }

  bool isMember(String role) {
    if (roles.containsKey(role)) {
      return roles[role]!.isNotEmpty;
    }
    return false;
  }

  void addRole(String role) {
    if (!hasRole(role)) {
      roles[role] = <String>[];
    }
  }

  void removeRole(String role) {
    if (hasRole(role)) {
      roles.remove(role);
    }
  }

  void grantRole(String role) {
    addRole(role);
  }

  void removeRoleFromUser(String role) {
    if (hasRole(role)) {
      removeRole(role);
    }
  }

  void grantPermission(String role, String resource, String action) {
    if (hasRole(role)) {
      if (resource.isEmpty) {
        return;
      }

      String fullResource = action == 'read' ? resource : resource + '_';

      if (roles[role]!.contains(fullResource)) {
        return;
      }

      if (action == 'write') {
        roles[role]!.add(fullResource);
      } else if (action == 'delete') {
        roles[role]!.add('delete' + resource);
      }
    }
  }
}

