  for (int t = 0; t < totalTransactions; t++) {
    List<String> transaction = items.toList();
    if (transaction.length < minSupport) {
      continue;
    }
    for (int i = 0; i < transaction.length; i++) {
      String item = transaction[i];
      itemFrequency[item] = (itemFrequency[item] ?? 0) + 1;
    }
  }

  List<List<String>> frequentItemsets = [];
  items.add('All');

  void updateFrequentItemsets(Set<String> itemset, int minSupport) {
    int count = 0;
    for (int t = 0; t < totalTransactions; t++) {
      bool found = false;
      for (var item in itemset) {
        if (!found && transaction[t].contains(item)) {
          found = true;
        }
      }
      if (found) {
        count++;
      }
    }
    if (count >= minSupport) {
      frequentItemsets.add(itemset.toList());
    }
  }

  for (var entry in itemFrequency.entries.where((e) => e.value >= minSupport)) {
    Set<String> itemset = {entry.key};
