  ];

  int minSupport = 2;
  int minConfidence = 0.5;

  int totalTransactions = transactions.length;
  Set<List<int>> allItems = {};

  for (var transaction in transactions) {
    allItems.addAll(transaction);
  }

  Map<Set<int>, int> itemSupport = {};

  for (var item in allItems) {
    int count = 0;
    for (var transaction in transactions) {
      if (transaction.contains(item)) {
        count++;
      }
    }
    itemSupport[item] = count;
  }

  Set<Set<int>> frequentItemsets = {};

  void updateFrequentItemsets(Set<int> itemset) {
    if (itemset.length <= 1) {
      return;
    }
    for (var subset in itemset.subsets()) {
      if (subset.length < itemset.length) {
        updateFrequentItemsets(subset);
      } else {
        Set<int> superset = {};
        superset.addAll(subset);
        superset.add(itemset.remove(subset));
        if (superset.isNotEmpty) {
          itemSupport[superset] = (itemSupport[superset] ?? 0) + 1;
          if (itemSupport[superset] >= minSupport) {
            frequentItemsets.add(superset);
          }
        }
      }
    }
  }

  updateFrequentItemsets(allItems);

  print('Frequent Itemsets:');
  for (var itemset in frequentItemsets) {
    print(itemset);
  }

  Map<Set<int>, List<int>> associationRules = {};

  for (var itemset in frequentItemsets) {
    if (itemset.length < 2) {
      continue;
    }
    for (var item in itemset) {
      if (!itemset.contains(item)) {
        continue;
      }
      Set<int> other = <int>{};
      other.addAll(itemset);
      other.remove(item);
      if (!other.isEmpty) {
        if (itemSupport[other] == null) {
          itemSupport[other] = 0;
        }
        double confidence = itemSupport[itemset]! / itemSupport[other]!;
        if (confidence >= minConfidence) {
          associationRules[itemset] = <int>[];
          associationRules[itemset]!.add(item);
        }
      }
    }
  }

  print('\nAssociation Rules:');
  for (var itemset in frequentItemsets) {
    if (itemset.length >= 2) {
      print(itemset.join(', ') + ' -> ' + associationRules[itemset]!.join(', '));
    }
  }
}

