  Rectangle get bounding => Rectangle.rectangle(x - width / 2, y - height / 2, width, height);

  Rectangle get half =>
      Rectangle.rectangle(x - width / 2, y - height / 2, width / 2, height / 2);

  bool contains(Point point) =>
      point.x >= x - width / 2 &&
      point.x <= x + width / 2 &&
      point.y >= y - height / 2 &&
      point.y <= y + height / 2;

  bool intersects(Rectangle other) =>
      !(other.x - other.width / 2 > x + width / 2 ||
          other.x + other.width / 2 < x - width / 2 ||
          other.y - other.height / 2 > y + height / 2 ||
          other.y + other.height / 2 < y - height / 2);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

