    [4, 2],
    [5, 1],
    [5, 2],
  ];

  final numPoints = points.length;

  final clusterAssignments = List.filled(numPoints, -1);

  final clusters = List<List<int>>.filled(k, <int>[]);

  for (var iter = 0; iter < maxIterations; iter++) {
    final changed = <int>[];

    for (var i = 0; i < numPoints; i++) {
      final centroidIdx = clusterAssignments[i];

      final neighbors = <int>[];
      for (var j = 0; j < numPoints; j++) {
        if (i == j) continue;

        if ((points[i][0] - points[j][0]).abs() +
            (points[i][1] - points[j][1]).abs() <= eps) {
          neighbors.add(j);
        }
      }

      if (neighbors.isEmpty) continue;

      final centroids = <int>[centroidIdx];
      for (final v in neighbors) {
        if (clusterAssignments[v] == -1) {
          centroids.add(v);
        }
      }

      var best = @centroids;

      for (final v in centroids) {
        double minDist = double.infinity;
        int bestIdx = -1;

        for (var j = 0; j < numPoints; j++) {
          if (j == v) continue;

          final dist = (points[j][0] - points[v][0]).abs() +
              (points[j][1] - points[v][1]).abs();
          if (dist < minDist) {
            minDist = dist;
            bestIdx = j;
          }
        }

        if (bestIdx != -1) {
          final tmp = clusterAssignments[bestIdx];
          clusterAssignments[bestIdx] = v;
          clusterAssignments[v] = tmp;
          changed.add(v);
        }
      }
    }

    if (changed.isEmpty) break;
  }

  for (var i = 0; i < numPoints; i++) {
    final idx = clusterAssignments[i];
    if (idx == -1) continue;
    if (idx < 0) idx = -idx - 1;

    final cluster = clusters[idx];
    cluster.add(i);
