  KMeans(this.rng, this.k, this.points);

  int _distance(Point a, Point b) {
    final dx = a.x - b.x;
    final dy = a.y - b.y;
    return dx.abs() + dy.abs();
  }

  void _assignPointsToClusters(List<Point> points, List<int> clusterIds) {
    for (var i = 0; i < points.length; i++) {
      var minDistance = double.infinity;
      var bestCluster = -1;
      for (var c = 0; c < k; c++) {
        final distance = _distance(points[i], points[c]);
        if (distance < minDistance) {
          minDistance = distance;
          bestCluster = c;
        }
      }
      clusterIds[i] = bestCluster;
    }
  }

  void _reassignPointsToClusters(List<Point> points, List<int> clusterIds) {
    for (var i = 0; i < points.length; i++) {
      var minDistance = double.infinity;
      var bestCluster = -1;
      for (var c = 0; c < k; c++) {
        if (c != clusterIds[i]) {
          final distance = _distance(points[i], points[c]);
          if (distance < minDistance) {
            minDistance = distance;
            bestCluster = c;
          }
        }
      }
      clusterIds[i] = bestCluster;
    }
  }

  void _updateCentroids(List<Point> points, List<int> clusterIds) {
    var newPoints = <Point>[];
    for (var p in points) {
      if (clusterIds[p.index] == p.index) {
        newPoints.add(p);
      }
    }
    double cx = 0.0, cy = 0.0;
    for (var p in newPoints) {
      cx += p.x;
      cy += p.y;
    }
    if (newPoints.length > 0) {
      cx /= newPoints.length;
      cy /= newPoints.length;
    }
    for (var i = 0; i < points.length; i++) {
      if (clusterIds[i] == i) {
        points[i] = Point(cx, cy);
      }
    }
  }

  void _clusterPoints(List<Point> points, List<int> clusterIds) {
    var converged = false;
    var iterations = 0;
    while (!converged) {
      iterations++;
      converged = true;
      _assignPointsToClusters(points, clusterIds);
      _updateCentroids(points, clusterIds);
      _reassignPointsToClusters(points, clusterIds);
      for (var p in points) {
        if (_distance(p, points[clusterIds[p.index]]) < 2) {
          converged = false;
          break;
        }
      }
    }
    print('Converged in $iterations iteration(s).');
  }

  void fit() {
    _clusterPoints(points, List<int>.filled(points.length, -1));
  }
}

