        final double d = distance(points[j], x);
        if (d <= eps) {
          newPoints.add(points[j]);
        }
      }

      if (newPoints.length >= 2) {
        final int idx1 = rand.nextInt(newPoints.length);
        final int idx2 = rand.nextInt(newPoints.length);
        while (idx1 == idx2) {
          idx2 = (idx2 + 1) % newPoints.length;
        }
        final double dist1 = distance(newPoints[idx1], x);
        final double dist2 = distance(newPoints[idx2], x);
        if (dist1 < dist2) {
          centroid = List<double>.from(newPoints[idx1]);
        } else if (dist1 > dist2) {
          centroid = List<double>.from(newPoints[idx2]);
        }
      }
    }

    for (int i = 0; i < n; i++) {
      if (labels[i] == -1) {
        labels[i] = clusters.add(i);
